CustomJavaScriptEntry.Script:
(function () {
  console.log('[strip-channel-numbers] loaded');
  const numbers = new Map();   // channel id -> its channel number ('' if none or unknown)
  const pending = new Set();
  let fetching = false;
  const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Removes this channel's own number from the start of its title, and nothing else.
  const stripCard = (card, num) => {
    const line = card.querySelector('.cardText-first') || card.querySelector('.cardText');
    if (!line || line.dataset.numStripped === line.textContent) return;
    if (num) {
      const re = new RegExp('^\\s*' + escape(num) + '\\s+');
      const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
      let node;
      while ((node = walker.nextNode())) {
        if (node.nodeValue.trim()) { node.nodeValue = node.nodeValue.replace(re, ''); break; }
      }
    }
    line.dataset.numStripped = line.textContent;   // checked again if Jellyfin reuses the card
  };

  // Looks up the channel numbers of new cards, 100 at a time.
  const fetchNumbers = async () => {
    if (fetching || !pending.size || !window.ApiClient) return;
    fetching = true;
    const ids = [...pending].slice(0, 100);
    ids.forEach(id => pending.delete(id));
    try {
      const res = await ApiClient.getItems(ApiClient.getCurrentUserId(), { Ids: ids.join(',') });
      ids.forEach(id => numbers.set(id, ''));
      (res.Items || []).forEach(i => numbers.set(i.Id, i.ChannelNumber || ''));
    } catch (e) {
      console.warn('[strip-channel-numbers] lookup failed', e);
      ids.forEach(id => numbers.set(id, ''));       // leave those titles untouched
    }
    fetching = false;
    strip();
  };

  const strip = () => {
    document.querySelectorAll('[data-type="TvChannel"][data-id]').forEach(card => {
      const id = card.dataset.id;
      if (numbers.has(id)) stripCard(card, numbers.get(id));
      else pending.add(id);
    });
    fetchNumbers();
  };

  let queued = false;
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; strip(); });
  }).observe(document.body, { childList: true, subtree: true });
  strip();
})();
